#include "UI/MainToolBar.h"
#include <QActionGroup>
namespace myvocal { MainToolBar::MainToolBar(QWidget*p):QToolBar(p){setIconSize(QSize(18,18));setMovable(false);m_group=new QActionGroup(this);m_group->setExclusive(true);const QList<QPair<QString,EditTool>> tools={{"Select",EditTool::Select},{"Pen",EditTool::Pen},{"Pen+",EditTool::PenPlus},{"Eraser",EditTool::Eraser},{"Knife",EditTool::Knife},{"Pitch",EditTool::Pitch},{"Pitch Line",EditTool::PitchLine},{"Vibrato",EditTool::Vibrato},{"Zoom",EditTool::Zoom},{"Pan",EditTool::Pan}};for(const auto&it:tools){auto*a=addAction(it.first);a->setCheckable(true);a->setToolTip(it.first);a->setData(static_cast<int>(it.second));m_group->addAction(a);connect(a,&QAction::triggered,this,[this,a](){emit toolChanged(static_cast<EditTool>(a->data().toInt()));});if(it.second==EditTool::Select)a->setChecked(true);}addSeparator();auto*snap=addAction("Snap");snap->setCheckable(true);snap->setChecked(true);connect(snap,&QAction::toggled,this,&MainToolBar::snapToggled);auto*grid=addAction("Grid");grid->setCheckable(true);grid->setChecked(true);connect(grid,&QAction::toggled,this,&MainToolBar::gridToggled);}}
